Clase Nodo
    Publico Definir valor Como Entero;
    Publico Definir siguiente Como Nodo;
FinClase

Proceso EjecutarNodoEnlazado
    Definir Mutable v1 Como Entero <- 0;
    Definir Mutable v2 Como Entero <- 0;
    Leer v1;
    Leer v2;
    Definir primero Como Nodo <- Nuevo Nodo();
    Definir segundo Como Nodo <- Nuevo Nodo();
    primero.valor <- v1;
    segundo.valor <- v2;
    primero.siguiente <- segundo;
    Escribir primero.siguiente.valor;
FinProceso
